create or replace function public.verify_pepper_pin(member_id_input uuid, pin_input text) returns boolean language sql security definer set search_path=public,extensions as $$ select exists(select 1 from public.household_members where id=member_id_input and pin_hash is not null and pin_hash=crypt(pin_input,pin_hash)); $$; revoke all on function public.verify_pepper_pin(uuid,text) from public; grant execute on function public.verify_pepper_pin(uuid,text) to service_role;
